/**
 * Test flow for sendNotification action
 * Demonstrates sending a notification
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testSendNotification = Flow(
    {
        $id: Now.ID['test_send_notification_flow'],
        name: 'Test Send Notification',
        description: 'Tests the sendNotification core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_send_notification_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        wfa.action(
            action.core.sendNotification,
            { $id: Now.ID['test_send_notification_action'] },
            {
                notification: 'incident.assigned',
                record: wfa.dataPill(_params.trigger.current.sys_id, 'reference'),
                table_name: 'incident',
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_send_notification_log'] },
            {
                log_level: 'info',
                log_message: `sendNotification outputs: (no outputs)`,
            }
        )
    }
)
